css:
.leanlaunch-container {
    padding: 28px;
    background: linear-gradient(135deg, #1a0533 0%, #0d1b4b 48%, #0a2e1a 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #f1f5f9;
}

.leanlaunch-container h1, .leanlaunch-container h2, .leanlaunch-container h3 {
    margin: 0;
    color: #ffffff;
}

.leanlaunch-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;
    background: rgba(255,255,255,0.06);
    backdrop-filter: blur(18px);
    -webkit-backdrop-filter: blur(18px);
    border: 1px solid rgba(255,255,255,0.12);
    border-radius: 20px;
    padding: 26px 30px;
    margin-bottom: 24px;
}

.leanlaunch-header-left {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.leanlaunch-badge {
    display: inline-block;
    align-self: flex-start;
    padding: 4px 10px;
    border-radius: 999px;
    background: rgba(167,139,250,0.18);
    border: 1px solid rgba(167,139,250,0.35);
    color: #c4b5fd;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    font-weight: 600;
}

.leanlaunch-header h1 {
    font-size: 1.75rem;
    font-weight: 700;
    background: linear-gradient(135deg, #a78bfa, #60a5fa 55%, #34d399);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.leanlaunch-subtitle {
    margin: 0;
    color: #cbd5e1;
    font-size: 0.95rem;
}

.leanlaunch-header-right {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 8px;
}

.leanlaunch-round-chip {
    display: inline-flex;
    align-items: baseline;
    gap: 6px;
    background: rgba(96,165,250,0.15);
    border: 1px solid rgba(96,165,250,0.35);
    border-radius: 12px;
    padding: 10px 16px;
}

.leanlaunch-round-label {
    color: #93c5fd;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.15em;
    font-weight: 600;
}

.leanlaunch-round-current {
    font-size: 1.6rem;
    font-weight: 800;
    color: #ffffff;
}

.leanlaunch-round-sep {
    color: #93c5fd;
    font-size: 0.9rem;
}

.leanlaunch-round-max {
    color: #ffffff;
    font-size: 1.05rem;
    font-weight: 600;
}

.leanlaunch-weeks-chip {
    padding: 5px 12px;
    border-radius: 999px;
    background: rgba(52,211,153,0.15);
    border: 1px solid rgba(52,211,153,0.4);
    color: #86efac;
    font-size: 0.78rem;
    font-weight: 600;
    letter-spacing: 0.05em;
}

.leanlaunch-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 16px;
    margin-bottom: 24px;
}

.leanlaunch-kpi-card {
    background: rgba(255,255,255,0.06);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    border: 1px solid rgba(255,255,255,0.12);
    border-radius: 16px;
    padding: 20px 22px;
    transition: transform 0.2s ease, background 0.2s ease;
    position: relative;
    overflow: hidden;
}

.leanlaunch-kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
    background: linear-gradient(90deg, #a78bfa, #60a5fa);
}

.leanlaunch-kpi-card.leanlaunch-kpi-cash::before { background: linear-gradient(90deg, #34d399, #60a5fa); }
.leanlaunch-kpi-card.leanlaunch-kpi-runway::before { background: linear-gradient(90deg, #60a5fa, #a78bfa); }
.leanlaunch-kpi-card.leanlaunch-kpi-validation::before { background: linear-gradient(90deg, #a78bfa, #f472b6); }
.leanlaunch-kpi-card.leanlaunch-kpi-lois::before { background: linear-gradient(90deg, #fbbf24, #f472b6); }
.leanlaunch-kpi-card.leanlaunch-kpi-paying::before { background: linear-gradient(90deg, #34d399, #fbbf24); }

.leanlaunch-kpi-card:hover {
    background: rgba(255,255,255,0.1);
    transform: translateY(-3px);
}

.leanlaunch-kpi-label {
    color: #94a3b8;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    font-weight: 600;
    margin-bottom: 10px;
}

.leanlaunch-kpi-value {
    font-size: 1.75rem;
    font-weight: 800;
    color: #ffffff;
    letter-spacing: -0.01em;
    line-height: 1.1;
}

.leanlaunch-kpi-sub {
    margin-top: 6px;
    color: #64748b;
    font-size: 0.72rem;
    font-style: italic;
}

.leanlaunch-briefing {
    background: rgba(255,255,255,0.05);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
    border: 1px solid rgba(167,139,250,0.25);
    border-radius: 18px;
    padding: 26px 28px;
    margin-bottom: 20px;
    box-shadow: 0 6px 28px rgba(124,58,237,0.15);
}

.leanlaunch-briefing-top {
    display: flex;
    align-items: flex-start;
    gap: 16px;
    margin-bottom: 14px;
}

.leanlaunch-briefing-tag {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 52px;
    height: 52px;
    border-radius: 14px;
    background: linear-gradient(135deg, #a78bfa, #60a5fa);
    color: #0f172a;
    font-size: 1.1rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    box-shadow: 0 4px 18px rgba(167,139,250,0.4);
}

.leanlaunch-briefing-titles h2 {
    font-size: 1.4rem;
    font-weight: 700;
    margin-bottom: 2px;
}

.leanlaunch-briefing-subtitle {
    margin: 0;
    color: #cbd5e1;
    font-size: 0.9rem;
}

.leanlaunch-briefing-context {
    color: #e2e8f0;
    font-size: 0.95rem;
    line-height: 1.55;
    margin: 0 0 12px 0;
}

.leanlaunch-briefing-question {
    color: #fde68a;
    font-size: 1rem;
    font-weight: 600;
    margin: 0;
    padding: 10px 14px;
    border-left: 3px solid #fbbf24;
    background: rgba(251,191,36,0.08);
    border-radius: 0 10px 10px 0;
}

.leanlaunch-controls {
    background: rgba(255,255,255,0.05);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
    border: 1px solid rgba(255,255,255,0.12);
    border-radius: 18px;
    padding: 24px 26px;
    margin-bottom: 20px;
}

.leanlaunch-controls h3 {
    font-size: 1.05rem;
    margin-bottom: 16px;
    color: #e0e7ff;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-weight: 700;
}

.leanlaunch-field {
    display: flex;
    flex-direction: column;
    gap: 6px;
    margin-bottom: 14px;
}

.leanlaunch-field label {
    color: #cbd5e1;
    font-size: 0.82rem;
    font-weight: 600;
}

.leanlaunch-controls select,
.leanlaunch-controls input[type="number"] {
    background: rgba(15,23,42,0.6);
    border: 1px solid rgba(148,163,184,0.3);
    color: #f1f5f9;
    border-radius: 10px;
    padding: 10px 14px;
    width: 100%;
    font-size: 0.95rem;
    transition: border-color 0.2s ease, background 0.2s ease;
}

.leanlaunch-controls select:focus,
.leanlaunch-controls input[type="number"]:focus {
    outline: none;
    border-color: #a78bfa;
    background: rgba(15,23,42,0.85);
    box-shadow: 0 0 0 3px rgba(167,139,250,0.2);
}

.leanlaunch-controls select option {
    background: #1e1b4b;
    color: #f1f5f9;
}

.leanlaunch-buttons {
    display: flex;
    gap: 12px;
    margin-top: 6px;
    flex-wrap: wrap;
}

.leanlaunch-container .btn.btn-primary {
    background: linear-gradient(135deg, #a78bfa, #6366f1);
    border: none;
    border-radius: 10px;
    padding: 11px 22px;
    font-weight: 700;
    color: #ffffff;
    letter-spacing: 0.02em;
    box-shadow: 0 6px 18px rgba(99,102,241,0.35);
    transition: transform 0.15s ease, box-shadow 0.2s ease;
}

.leanlaunch-container .btn.btn-primary:hover {
    transform: translateY(-1px);
    box-shadow: 0 10px 26px rgba(99,102,241,0.5);
}

.leanlaunch-container .btn.btn-outline-secondary {
    background: transparent;
    border: 1px solid rgba(148,163,184,0.4);
    color: #cbd5e1;
    border-radius: 10px;
    padding: 10px 18px;
    font-weight: 600;
}

.leanlaunch-container .btn.btn-outline-secondary:hover {
    background: rgba(148,163,184,0.15);
    color: #ffffff;
}

.leanlaunch-hint {
    background: rgba(251,191,36,0.08);
    border: 1px solid rgba(251,191,36,0.3);
    border-left: 4px solid #fbbf24;
    border-radius: 12px;
    padding: 14px 18px;
    color: #fde68a;
    font-size: 0.92rem;
    line-height: 1.55;
    margin-bottom: 22px;
    min-height: 52px;
}

.leanlaunch-hint strong {
    color: #fef3c7;
}

.leanlaunch-chart-wrap {
    background: rgba(255,255,255,0.05);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    border: 1px solid rgba(255,255,255,0.12);
    border-radius: 18px;
    padding: 22px 24px;
    margin-bottom: 22px;
    height: 360px;
}

.leanlaunch-chart-wrap canvas {
    width: 100% !important;
    height: 100% !important;
}

.leanlaunch-history {
    background: rgba(255,255,255,0.04);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 18px;
    padding: 22px 24px;
}

.leanlaunch-history h3 {
    font-size: 1rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-weight: 700;
    color: #e0e7ff;
    margin-bottom: 14px;
}

.leanlaunch-history table {
    width: 100%;
    color: #e2e8f0;
    border-collapse: collapse;
}

.leanlaunch-history table thead th {
    color: #94a3b8;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-weight: 700;
    border-bottom: 1px solid rgba(148,163,184,0.25);
    padding: 10px 12px;
    text-align: left;
}

.leanlaunch-history table tbody td {
    padding: 10px 12px;
    border-bottom: 1px solid rgba(148,163,184,0.1);
    font-size: 0.9rem;
}

.leanlaunch-history table tbody tr:hover {
    background: rgba(255,255,255,0.04);
}

@media (max-width: 768px) {
    .leanlaunch-container { padding: 16px; }
    .leanlaunch-header {
        flex-direction: column;
        align-items: flex-start;
        padding: 20px;
    }
    .leanlaunch-header-right {
        align-items: flex-start;
        width: 100%;
    }
    .leanlaunch-kpi-grid {
        grid-template-columns: repeat(2, 1fr);
    }
    .leanlaunch-kpi-value { font-size: 1.35rem; }
    .leanlaunch-briefing-top { flex-direction: column; }
    .leanlaunch-chart-wrap { height: 280px; }
}

