    class LeanLaunchAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'LeanLaunch — NiduApp';
            this.version = '1.1.0';
            this.ROUNDS = ROUNDS;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 198000,
                    burnRate: 18000,
                    runway: 11.0,
                    validation: 0,
                    lois: 0,
                    paying: 0,
                    hypothesesValidated: 0,
                    pivotCount: 0,
                    killed: false,
                    zoomSignal: 0,
                    validationHistory: [],
                    runwayHistory: [],
                    cashHistory: [],
                    roundNotes: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    primary: 'problem',
                    budget: 15,
                    intensity: 'open'
                };
            }
            var self = this;
            setTimeout(function() { self._updateBriefing(state); }, 60);
        }

        validateDecisions(decisions) {
            const p = document.getElementById('primaryInput');
            const b = document.getElementById('budgetInput');
            const i = document.getElementById('intensityInput');
            if (p) decisions.primary = p.value;
            if (b) decisions.budget = parseFloat(b.value);
            if (i) decisions.intensity = i.value;

            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const spec = this.ROUNDS[Math.min(round - 1, this.ROUNDS.length - 1)];

            if (!decisions.primary) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warn_primary'), 'warning');
                return false;
            }
            if (isNaN(decisions.budget) || decisions.budget < spec.budgetMin || decisions.budget > spec.budgetMax) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warn_budget'), 'warning');
                return false;
            }
            if (!decisions.intensity) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warn_intensity'), 'warning');
                return false;
            }

            this._updateBriefing(state);
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let validationDelta = 0;
            let cashSpend = 9000; // 2 weeks of burn per round (burn 18K/mo)
            let loisDelta = 0;
            let payingDelta = 0;
            let hypothesesValidated = 0;
            let note = '';

            if (round === 1) {
                const scores = {
                    problem:  { open: 22, demo: 14, pitch:  6 },
                    solution: { open: 10, demo: 15, pitch:  6 },
                    channel:  { open:  8, demo:  6, pitch:  5 },
                    price:    { open: 10, demo:  8, pitch: -4 }
                };
                validationDelta = scores[d.primary][d.intensity];
                if (d.budget < 8) validationDelta -= 6;
                else if (d.budget >= 15) validationDelta += 3;

                cashSpend += 120 * d.budget + 1500;

                if (d.primary === 'problem' && d.intensity === 'open' && d.budget >= 12) {
                    loisDelta = 1;
                    hypothesesValidated = 1;
                    ds.zoomSignal += 2;
                    note = 'Problema validado: 2 dolores recurrentes confirmados (cartera vencida y conciliación bancaria). 1 LOI verbal.';
                } else if (d.primary === 'solution' && d.intensity === 'demo') {
                    ds.zoomSignal += 1;
                    note = 'Señal de entusiasmo con la demo, pero cero compromiso escrito. Riesgo de sesgo de cortesía.';
                } else if (d.primary === 'price' && d.intensity === 'pitch') {
                    note = 'Pitcheaste precio antes de validar el problema. Respuestas dominadas por «suena interesante».';
                } else if (d.budget < 8) {
                    note = 'Pocas entrevistas para concluir. Aprendizaje superficial, decisiones a ciegas.';
                } else {
                    note = 'Aprendizaje mixto. Revisa si el patrón que viste es dolor real o cortesía.';
                }
            } else if (round === 2) {
                const scopeCost = { landing: 3000, concierge: 1500, core: 14000, full: 38000 };
                const scopeVal  = { landing: 14, concierge: 22, core: 6, full: -14 };
                validationDelta = scopeVal[d.primary] || 0;
                cashSpend += scopeCost[d.primary] || 5000;

                if (d.intensity === 'narrow')       validationDelta += 4;
                else if (d.intensity === 'wide')    validationDelta -= 6;

                if (ds.hypothesesValidated === 0 && (d.primary === 'core' || d.primary === 'full')) {
                    validationDelta -= 10;
                    note = 'Construiste antes de validar el problema. Semanas-hombre invertidas sin evidencia de dolor real.';
                } else if (d.primary === 'concierge') {
                    loisDelta = 1;
                    ds.zoomSignal += 2;
                    note = 'Concierge MVP: aprendizaje profundo, cero deuda técnica, 1 LOI convertida en pre-pago parcial.';
                } else if (d.primary === 'landing') {
                    ds.zoomSignal += 1;
                    note = 'Landing + Stripe: mides conversión en días. Útil si Ronda 1 validó el problema.';
                } else if (d.primary === 'core') {
                    note = 'Dashboard de recaudo. Funcional pero sin validación transversal.';
                } else if (d.primary === 'full') {
                    note = 'Producto completo construido. 0 clientes para probarlo. Clásico error de Lean Startup.';
                }
                if (d.budget < (scopeCost[d.primary] || 5000) * 0.6) {
                    validationDelta -= 4;
                    note += '<br>Presupuesto insuficiente: entregable a medias, moral del equipo afectada.';
                }
            } else if (round === 3) {
                const metricVal = { trial_to_paid: 20, loi_signed: 18, ctr: 4, followers: -2 };
                const thresholdVal = { strict: 6, medium: 2, loose: -8 };
                validationDelta = (metricVal[d.primary] || 0) + (thresholdVal[d.intensity] || 0);
                cashSpend += 1200 * d.budget + 800;

                if (d.primary === 'ctr' || d.primary === 'followers') {
                    note = 'Métrica de vanidad como principal. Riesgo real de celebrar ruido y racionalizar un fracaso.';
                } else if (d.intensity === 'strict') {
                    hypothesesValidated += 1;
                    note = 'Umbral ex-ante bien definido. Te obliga a decidir sin sesgo post-hoc.';
                } else if (d.intensity === 'loose') {
                    note = 'Umbral flojo invita a racionalizar. En Ronda 4 te costará tomar la decisión.';
                } else {
                    note = 'Umbral medio razonable, pero deja espacio a interpretación subjetiva.';
                }

                // El experimento entrega datos reales: trial-to-paid 0%
                if (d.primary === 'trial_to_paid') {
                    note += '<br>Resultado experimento: trial-to-paid 0% (0 de ' + d.budget + ' conjuntos pagaron).';
                } else if (d.primary === 'loi_signed') {
                    loisDelta = Math.min(Math.floor(d.budget / 3), 2);
                    note += '<br>Resultado experimento: ' + loisDelta + ' LOIs firmadas sobre ' + d.budget + ' conjuntos.';
                } else if (d.primary === 'ctr') {
                    note += '<br>Resultado: CTR 3.2% (no dice nada sobre demanda real).';
                } else {
                    note += '<br>Resultado: +180 seguidores (no dice nada sobre demanda real).';
                }
            } else if (round === 4) {
                const decisionScores = {
                    persevere:      -12,
                    zoom_in:        ds.zoomSignal >= 2 ? 18 : 6,
                    zoom_out:        -4,
                    customer_pivot: ds.hypothesesValidated >= 2 ? 4 : -16,
                    problem_pivot:   ds.hypothesesValidated >= 1 ? 10 : -6,
                    kill:           ds.runway < 5 ? 8 : -14
                };
                validationDelta = decisionScores[d.primary] || 0;
                if (d.intensity === 'data')      validationDelta += 5;
                else if (d.intensity === 'gut')  validationDelta -= 4;

                // Inversión próxima ronda aplicada parcialmente
                cashSpend += Math.min(Math.max(d.budget, 0), 80000) * 0.35;

                if (d.primary === 'persevere') {
                    note = 'Persevere con trial-to-paid 0%. Clásico sesgo de continuación frente a evidencia negativa. El onboarding no es el problema.';
                } else if (d.primary === 'zoom_in') {
                    ds.pivotCount += 1;
                    note = ds.zoomSignal >= 2
                        ? 'Zoom-in a la feature que sí mostró tracción. Pivot disciplinado con evidencia.'
                        : 'Zoom-in sin señal previa sólida. Estás escogiendo «algo» por no decidir.';
                } else if (d.primary === 'zoom_out') {
                    ds.pivotCount += 1;
                    note = 'Zoom-out amplía la propuesta antes de validarla. Riesgo de repetir el error en mayor escala.';
                } else if (d.primary === 'customer_pivot') {
                    ds.pivotCount += 1;
                    ds.hypothesesValidated = Math.max(0, ds.hypothesesValidated - 1);
                    note = ds.hypothesesValidated >= 1
                        ? 'Customer pivot con alguna validación previa. Necesitas re-validar hipótesis con PyMEs desde cero.'
                        : 'Pivot a PyMEs sin evidencia del nuevo segmento. Repites el error del principio en un segmento nuevo.';
                } else if (d.primary === 'problem_pivot') {
                    ds.pivotCount += 1;
                    note = 'Problem pivot dentro del mismo segmento. Aprovecha el conocimiento de administradoras, ataca otro dolor.';
                } else if (d.primary === 'kill') {
                    if (ds.runway >= 5) {
                        ds.killed = true;
                        note = 'Kill prematuro con ' + ds.runway.toFixed(1) + ' meses de runway por usar. Mataste una hipótesis, no la empresa.';
                    } else {
                        note = 'Kill con runway corto: decisión honesta, capital residual devuelto a LPs.';
                    }
                }
            } else if (round === 5) {
                if (ds.killed) {
                    validationDelta = -5;
                    cashSpend = 600;
                    note = 'Empresa cerrada en Ronda 4. El pitch se convierte en post-mortem con el inversionista.';
                } else {
                    const narrativeScores = { learning: 18, traction: 12, vision: 4, optimism: -10 };
                    const milestoneScores = { paying: 10, loi: 6, mau: -2, feature: -6 };
                    validationDelta = (narrativeScores[d.primary] || 0) + (milestoneScores[d.intensity] || 0);

                    const askRealism = (d.budget >= 150000 && d.budget <= 600000) ? 5 : (d.budget > 1200000 ? -8 : -3);
                    validationDelta += askRealism;
                    cashSpend = 800;

                    if (d.primary === 'learning' && d.intensity === 'paying' && askRealism > 0) {
                        note = 'Pitch honesto con milestone medible y ask realista. El socio pide term-sheet follow-up.';
                    } else if (d.primary === 'optimism') {
                        note = '«Casi lo logramos» no compra runway. El inversionista pide datos que no tienes.';
                    } else if (d.intensity === 'feature') {
                        note = 'Milestone orientado a entregable técnico, no a demanda. El inversionista pregunta: ¿y quién paga?';
                    } else if (askRealism < 0 && d.budget > 1200000) {
                        note = 'Ask desproporcionado al stage. El inversionista cierra la conversación.';
                    } else {
                        note = 'Pitch recibido con reservas. Follow-up condicionado a cumplir milestones cuantitativos.';
                    }
                }
            }

            ds.cash = Math.max(0, ds.cash - cashSpend);
            ds.validation = Math.max(0, Math.min(100, (ds.validation || 0) + validationDelta));
            ds.lois = (ds.lois || 0) + loisDelta;
            ds.paying = (ds.paying || 0) + payingDelta;
            ds.hypothesesValidated = (ds.hypothesesValidated || 0) + hypothesesValidated;
            ds.runway = ds.cash > 0 ? parseFloat((ds.cash / ds.burnRate).toFixed(2)) : 0;

            ds.validationHistory.push(ds.validation);
            ds.runwayHistory.push(parseFloat(ds.runway.toFixed(1)));
            ds.cashHistory.push(Math.round(ds.cash));
            ds.roundNotes.push(note);

            const result = {
                period: round,
                primary: d.primary,
                intensity: d.intensity,
                budget: d.budget,
                cashSpend: Math.round(cashSpend),
                validationDelta: Math.round(validationDelta),
                validation: Math.round(ds.validation),
                lois: ds.lois,
                paying: ds.paying,
                runway: parseFloat(ds.runway.toFixed(1)),
                cash: Math.round(ds.cash),
                note: note
            };

            var _sc = this._score(ds);
            ds.score = _sc;
            ds.performance = { overallScore: _sc, grade: this._grade(_sc) };
            result.score = _sc;
            result.overallScore = _sc;

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: round + 1 });
                self._renderHint(result, ds);
            }, 500);

            return result;
        }

        _updateBriefing(state) {
            const period = state.currentPeriod || 1;
            const idx = Math.min(Math.max(period - 1, 0), this.ROUNDS.length - 1);
            const r = this.ROUNDS[idx];
            const g = function(id) { return document.getElementById(id); };

            if (g('roundTag')) g('roundTag').textContent = r.tag;
            if (g('roundWeeks')) g('roundWeeks').textContent = r.weeks;
            if (g('roundTitle')) g('roundTitle').textContent = r.title;
            if (g('roundSubtitle')) g('roundSubtitle').textContent = r.subtitle;
            if (g('roundContext')) g('roundContext').textContent = r.context;
            if (g('roundQuestion')) g('roundQuestion').textContent = r.question;
            if (g('primaryLabel')) g('primaryLabel').textContent = r.primaryLabel;
            if (g('budgetLabel')) g('budgetLabel').textContent = r.budgetLabel + ' (' + r.budgetMin + '–' + r.budgetMax + r.budgetUnit + ')';
            if (g('intensityLabel')) g('intensityLabel').textContent = r.intensityLabel;

            const primary = g('primaryInput');
            if (primary) {
                primary.innerHTML = '';
                r.primaryOptions.forEach(function(o) {
                    const opt = document.createElement('option');
                    opt.value = o.value;
                    opt.textContent = o.label;
                    primary.appendChild(opt);
                });
                primary.value = r.primaryOptions[0].value;
            }

            const intensity = g('intensityInput');
            if (intensity) {
                intensity.innerHTML = '';
                r.intensityOptions.forEach(function(o) {
                    const opt = document.createElement('option');
                    opt.value = o.value;
                    opt.textContent = o.label;
                    intensity.appendChild(opt);
                });
                intensity.value = r.intensityOptions[0].value;
            }

            const budget = g('budgetInput');
            if (budget) {
                budget.min = r.budgetMin;
                budget.max = r.budgetMax;
                budget.step = r.budgetStep || 1;
                budget.value = r.budgetDefault;
            }
        }

        _renderHint(result, ds) {
            const hint = document.getElementById('hintBox');
            if (!hint) return;
            let msg = '';
            if (result.note) msg += '<strong>Nota del facilitador:</strong> ' + result.note;
            if (ds.runway < 4 && ds.runway > 0) msg += '<br>⚠ Runway bajo: ' + ds.runway.toFixed(1) + ' meses. Toda próxima decisión debe ser financiable.';
            if (ds.validation < 20 && result.period >= 2) msg += '<br>📉 Validación débil: revisa si estás aprendiendo o solo construyendo.';
            if (ds.killed) msg += '<br>🛑 NiduApp cerrada. Capital residual devuelto.';
            hint.innerHTML = msg || '<em>Sin alertas — sigue iterando.</em>';
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cash',
                (v) => 'USD ' + Math.round(v || 0).toLocaleString());
            uiManager.bind('runwayDisplay', 'domainState.runway',
                (v) => (v || 0).toFixed(1) + ' meses');
            uiManager.bind('validationDisplay', 'domainState.validation',
                (v) => Math.round(v || 0) + ' / 100');
            uiManager.bind('loiDisplay', 'domainState.lois');
            uiManager.bind('payingDisplay', 'domainState.paying');
        }

        getChartConfig() {
            return {
                validationChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Validación (0–100)',
                                data: [],
                                borderColor: '#a78bfa',
                                backgroundColor: 'rgba(167,139,250,0.18)',
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                yAxisID: 'y'
                            },
                            {
                                label: 'Runway (meses)',
                                data: [],
                                borderColor: '#60a5fa',
                                backgroundColor: 'rgba(96,165,250,0.08)',
                                borderWidth: 3,
                                borderDash: [6, 4],
                                fill: false,
                                tension: 0.25,
                                yAxisID: 'y1'
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Validación vs. Runway', color: '#ffffff', font: { size: 14 } },
                            legend: { labels: { color: '#e2e8f0' } }
                        },
                        scales: {
                            x: { ticks: { color: '#cbd5e1' }, grid: { color: 'rgba(255,255,255,0.08)' } },
                            y: {
                                position: 'left',
                                beginAtZero: true,
                                max: 100,
                                title: { display: true, text: 'Validación', color: '#a78bfa' },
                                ticks: { color: '#a78bfa' },
                                grid: { color: 'rgba(255,255,255,0.08)' }
                            },
                            y1: {
                                position: 'right',
                                beginAtZero: true,
                                title: { display: true, text: 'Runway (meses)', color: '#60a5fa' },
                                ticks: { color: '#60a5fa' },
                                grid: { drawOnChartArea: false }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const v = state.domainState.validationHistory || [];
            const r = state.domainState.runwayHistory || [];
            const labels = v.map(function(_, i) { return 'R' + (i + 1); });
            return {
                validationChart: {
                    labels: labels,
                    datasets: [
                        { data: v },
                        { data: r }
                    ]
                }
            };
        }

        _score(ds) {
            var val = Math.max(0, Math.min(100, ds.validation || 0));
            var loi = Math.max(0, Math.min(3, ds.lois || 0));
            var run = Math.max(0, Math.min(6, ds.runway || 0));
            return Math.max(0, Math.min(100, Math.round(val * 0.70 + (loi / 3) * 20 + (run / 6) * 10)));
        }
        _grade(score) {
            if (score >= 75) return 'A';
            if (score >= 50) return 'B';
            if (score >= 30) return 'C';
            return 'D';
        }
        getPerformanceSummary(history) {
            if (!history.length) return {};
            const last = history[history.length - 1];
            const ds = (last && last.domainState) ? last.domainState : {};
            const validation = ds.validation || 0;
            const lois = ds.lois || 0;
            const cash = ds.cash || 0;
            const runway = ds.runway || 0;
            const killed = !!ds.killed;
            const pivots = ds.pivotCount || 0;

            const t = function(k) { return window.mySimulation.t(k); };
            let perfKey, verdictKey;
            if (killed) { perfKey = 'perf_kill'; verdictKey = 'verdict_kill'; }
            else if (validation >= 70 && lois >= 3 && runway >= 4) { perfKey = 'perf_seriea'; verdictKey = 'verdict_seriea'; }
            else if (validation >= 50 && lois >= 1) { perfKey = 'perf_bridge'; verdictKey = 'verdict_bridge'; }
            else if (validation >= 30) { perfKey = 'perf_ext'; verdictKey = 'verdict_ext'; }
            else { perfKey = 'perf_runway'; verdictKey = 'verdict_runway'; }
            const performance = t(perfKey);
            const verdict = t(verdictKey);

            const insights = [];
            if (pivots === 0 && validation < 50 && !killed) {
                insights.push(t('ins_no_pivot'));
            }
            if (pivots >= 3) {
                insights.push(t('ins_many_pivot'));
            }
            if (lois === 0 && !killed) {
                insights.push(t('ins_no_loi'));
            }
            if (runway < 3 && !killed) {
                insights.push(t('ins_low_runway'));
            }
            if (ds.hypothesesValidated >= 2) {
                insights.push(t('ins_multi_hyp'));
            }
            if (!insights.length) insights.push(t('ins_good'));

            return {
                overallScore: this._score(ds),
                totalPeriods: history.length,
                totalValidation: Math.round(validation),
                finalCash: Math.round(cash),
                runway: parseFloat(runway.toFixed(1)),
                lois: lois,
                payingCustomers: ds.paying || 0,
                pivotCount: pivots,
                killed: killed,
                performance: performance,
                verdict: verdict,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.note) return results.note;
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'period', label: 'Ronda', i18nKey: 'col_round' },
                { key: 'results.primary', label: 'Decisión', i18nKey: 'col_primary' },
                { key: 'results.intensity', label: 'Modo', i18nKey: 'col_intensity' },
                { key: 'results.validationDelta', label: 'Δ Val.', i18nKey: 'col_delta',
                  formatter: function(v) { return (v > 0 ? '+' : '') + v; } },
                { key: 'results.validation', label: 'Validación', i18nKey: 'col_validation' },
                { key: 'results.cashSpend', label: 'Gasto', i18nKey: 'col_spend',
                  formatter: function(v) { return 'USD ' + (v || 0).toLocaleString(); } },
                { key: 'results.runway', label: 'Runway', i18nKey: 'col_runway',
                  formatter: function(v) { return v + ' m'; } },
                { key: 'results.lois', label: 'LOIs', i18nKey: 'col_lois' }
            ];
        }

        getPresets() { return null; }

        formatCompletionMessage(summary) {
            summary = summary || {};
            var t = function(k) { return window.mySimulation.t(k); };
            var score = (typeof summary.overallScore === 'number') ? summary.overallScore : 0;
            var perfL = summary.performance || '';
            var verdict = summary.verdict || '';
            var color = score >= 75 ? '#2a9d8f' : (score >= 50 ? '#e9c46a' : (score >= 30 ? '#f4a261' : '#e63946'));
            var money = function(v) { return 'USD ' + Math.round(v).toLocaleString(); };
            var kpis = [
                [t('comp_validation'), (typeof summary.totalValidation === 'number') ? summary.totalValidation : '-'],
                [t('comp_lois'), (summary.lois != null) ? summary.lois : '-'],
                [t('comp_runway'), (summary.runway != null) ? (summary.runway + ' m') : '-'],
                [t('comp_cash'), (summary.finalCash != null) ? money(summary.finalCash) : '-']
            ];
            var kpiRow = kpis.map(function(k) { return '<span style="display:inline-block;margin:4px 10px;"><strong>' + k[1] + '</strong> ' + k[0] + '</span>'; }).join('');
            var ins = summary.insights || [];
            var items = ins.map(function(x) { return '<li>' + x + '</li>'; }).join('');
            var insBlock = items ? ('<ul style="text-align:left;margin:12px auto 0;display:inline-block;">' + items + '</ul>') : '';
            var verdictBlock = verdict ? ('<p style="margin:8px auto;max-width:520px;">' + verdict + '</p>') : '';
            return '<div class="completion-message text-center p-4">' +
                '<h4 style="margin-bottom:8px;">' + t('comp_heading') + '</h4>' +
                '<div style="font-size:2.6rem;font-weight:800;color:' + color + ';">' + score + '/100</div>' +
                '<p class="lead" style="margin:2px 0;">' + t('comp_score_label') + '</p>' +
                '<p style="font-weight:700;color:' + color + ';">' + perfL + '</p>' +
                verdictBlock +
                '<p class="text-muted" style="margin:8px 0;">' + kpiRow + '</p>' +
                insBlock +
                '<hr class="my-3"><p class="text-muted">' + t('comp_thanks') + '</p></div>';
        }

